SELECT 'contrato tablas de canecas_productos (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(ENGINE AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(CREATE_OPTIONS AS CHAR),'<NULL>')) AS x FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos') h)='ffce2eb1ff93a915edbf67dbad0bcd7d', 'OK', 'DETENER') AS resultado;
SELECT 'contrato columnas de canecas_productos (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(ORDINAL_POSITION AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(IS_NULLABLE AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_DEFAULT AS CHAR),'<NULL>'), IFNULL(CAST(EXTRA AS CHAR),'<NULL>'), IFNULL(CAST(CHARACTER_SET_NAME AS CHAR),'<NULL>'), IFNULL(CAST(COLLATION_NAME AS CHAR),'<NULL>'), IFNULL(CAST(GENERATION_EXPRESSION AS CHAR),'<NULL>'), IFNULL(CAST(NUMERIC_PRECISION AS CHAR),'<NULL>'), IFNULL(CAST(NUMERIC_SCALE AS CHAR),'<NULL>'), IFNULL(CAST(DATETIME_PRECISION AS CHAR),'<NULL>'), IFNULL(CAST(CHARACTER_MAXIMUM_LENGTH AS CHAR),'<NULL>')) AS x FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos') h)='b205e33372a9623048126dd120f370ac', 'OK', 'DETENER') AS resultado;
SELECT 'contrato indices de canecas_productos (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_NAME AS CHAR),'<NULL>'), IFNULL(CAST(NON_UNIQUE AS CHAR),'<NULL>'), IFNULL(CAST(SEQ_IN_INDEX AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(SUB_PART AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(NULLABLE AS CHAR),'<NULL>'), IFNULL(CAST(IGNORED AS CHAR),'<NULL>')) AS x FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos') h)='12a31be2e76a9bdd1097817bee55a3da', 'OK', 'DETENER') AS resultado;
SELECT 'contrato foraneas de canecas_productos (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(k.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.ORDINAL_POSITION AS CHAR),'<NULL>'), IFNULL(CAST(k.COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(r.UPDATE_RULE AS CHAR),'<NULL>'), IFNULL(CAST(r.DELETE_RULE AS CHAR),'<NULL>')) AS x FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA='u611730801_Plataforma' AND k.TABLE_NAME='canecas_productos' AND k.REFERENCED_TABLE_NAME IS NOT NULL) h)='362d43fa9f6125e2acb24241821b51af', 'OK', 'DETENER') AS resultado;
SELECT 'contrato checks de canecas_productos (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(t.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(t.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(c.CHECK_CLAUSE AS CHAR),'<NULL>')) AS x FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA='u611730801_Plataforma' AND t.TABLE_NAME='canecas_productos') h)='70a357134af2ad71cda396b5f65901ac', 'OK', 'DETENER') AS resultado;
